package com.example.domain.model.i18n

internal object DuaNe2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_muawwidhat" to DuaText("तीन कुल (मुअव्विजात)", "(सूरह इखलास) भन: उहाँ अल्लाह एक हुनुहुन्छ। अल्लाह निरपेक्ष हुनुहुन्छ। उहाँले कसैलाई जन्माउनुभएन र उहाँ कसैबाट जन्मनुभएन। र उहाँको बराबरी कोही छैन।\n\n(सूरह फलक) भन: म बिहानका रबको शरण माग्छु, उहाँले सृष्टि गर्नुभएका कुराको खराबीबाट, अँध्यारो रातको खराबीबाट जब त्यो छाउँछ, गाँठामा फुक्नेहरूको खराबीबाट, र ईर्ष्यालुको खराबीबाट जब ऊ ईर्ष्या गर्छ।\n\n(सूरह नास) भन: म मानिसहरूका रबको शरण माग्छु, मानिसहरूका राजाको, मानिसहरूका पूज्यको, त्यो वसवसा हाल्नेको खराबीबाट जो (अल्लाहको जिक्र सुनेर) पछि हट्छ, जसले मानिसहरूका हृदयमा वसवसा हाल्छ, चाहे ऊ जिन्नहरूमध्येको होस् वा मानिसहरूमध्येको।", "बिहान-साँझ तीनवटै सूरह तीन-तीन पटक, र सुत्नुअघि हातमा फुकेर शरीरमा फेर्ने।", "बिहान-साँझ तीन पटक पढ्दा हरेक कुराबाट पर्याप्त हुन्छ।"),
        "dua_sabr" to DuaText("धैर्य र दृढताका लागि", "हे हाम्रा रब! हामीमाथि धैर्य खन्याउनुहोस्, हाम्रा खुट्टा दृढ पार्नुहोस् र काफिर समुदायविरुद्ध हामीलाई मद्दत गर्नुहोस्।", "कठिनाइ र मुकाबिलाको समयमा।", "तालूतको सेनाको दुआ।"),
        "dua_rabbana_innana_amanna" to DuaText("क्षमा र आगोबाट सुरक्षा", "हे हाम्रा रब! हामीले ईमान ल्यायौँ, त्यसैले हाम्रा पाप क्षमा गर्नुहोस् र हामीलाई आगोको सजायबाट बचाउनुहोस्।", "कुरआनी दुआ।", "धर्मपरायणहरूको गुणमा वर्णित दुआ।"),
        "dua_rabbana_hab_lana_rahmah" to DuaText("हाम्रो काममा मार्गदर्शन (असहाब-ए-कहफ)", "हे हाम्रा रब! हामीलाई आफ्नो तर्फबाट कृपा दिनुहोस् र हाम्रो काममा हाम्रा लागि सही मार्ग सहज बनाउनुहोस्।", "गुफावासीहरूको दुआ।", "निर्णय र कठिन परिस्थितिमा मार्गदर्शन।"),
        "dua_musa_faqir" to DuaText("जीविकाका लागि मूसा (अ.) को दुआ", "हे मेरा रब! तपाईंले ममाथि जुनसुकै भलाइ उतार्नुहोस्, म त्यसको आवश्यकतामा छु।", "जीविका र भलाइको माग — मदयनमा मूसा (अ.) को दुआ।", "यो दुआपछि अल्लाहले मूसा (अ.) लाई घर, रोजगार र श्रीमती दिनुभयो।"),
        "dua_ayyub" to DuaText("बिरामीमा अय्यूब (अ.) को दुआ", "(हे मेरा रब!) मलाई पीडाले छोएको छ र तपाईं सबै दयालुहरूभन्दा बढी दयालु हुनुहुन्छ।", "बिरामी र पीडामा।", "अल्लाहले अय्यूब (अ.) को पीडा हटाइदिनुभयो।"),
        "dua_husn_khatimah" to DuaText("मुस्लिम भएर मृत्यु (यूसुफ अ.)", "हे आकाश र पृथ्वीका सृष्टिकर्ता! तपाईं नै संसार र आखिरतमा मेरा संरक्षक हुनुहुन्छ। मलाई मुस्लिम अवस्थामा मृत्यु दिनुहोस् र असल मानिसहरूसँग मिलाउनुहोस्।", "राम्रो अन्त्यको दुआ।", "यूसुफ (अ.) को दुआ।"),
        "dua_shaitan_hamazat" to DuaText("शैतानका वसवसाबाट शरण", "हे मेरा रब! म शैतानहरूका वसवसाबाट तपाईंको शरण माग्छु, र हे मेरा रब! तिनीहरू मेरो नजिक आउनबाट पनि तपाईंको शरण माग्छु।", "शैतानी वसवसाबाट शरण।", "कुरआनी शरणको दुआ।"),
        "dua_bad_character" to DuaText("नराम्रो चरित्रबाट शरण", "हे अल्लाह! म नराम्रो चरित्र, नराम्रा कर्म र नराम्रा इच्छाहरूबाट तपाईंको शरण माग्छु।", "नराम्रो चरित्र, कर्म र इच्छाबाट शरण।", "नबी ﷺ को शरणको दुआ।"),
        "dua_zawal_nimah" to DuaText("कृपा खोसिनबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु तपाईंको कृपा हराउनबाट, तपाईंले दिएको सुरक्षा बदलिनबाट, तपाईंको अचानक सजायबाट र तपाईंको हरेक अप्रसन्नताबाट।", "कृपा खोसिने र अचानक संकटबाट शरण।", "नबी ﷺ को दुआ।"),
        "dua_useless_knowledge" to DuaText("बेकामको ज्ञानबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु त्यस्तो ज्ञानबाट जसले फाइदा गर्दैन, त्यस्तो हृदयबाट जो डराउँदैन, त्यस्तो मनबाट जो तृप्त हुँदैन, र त्यस्तो दुआबाट जुन स्वीकार हुँदैन।", "बेकामको ज्ञान र निडर हृदयबाट शरण।", "नबी ﷺ को शरणको दुआ।"),
        "dua_beneficial_knowledge" to DuaText("उपयोगी ज्ञान र हलाल जीविका", "हे अल्लाह! म तपाईंसँग उपयोगी ज्ञान, पवित्र जीविका र स्वीकार हुने कर्म माग्छु।", "फज्रको नमाजपछि।", "नबी ﷺ फज्रको सलामपछि यो दुआ गर्नुहुन्थ्यो।"),
        "dua_leprosy_diseases" to DuaText("गम्भीर रोगहरूबाट शरण", "हे अल्लाह! म तपाईंको शरण माग्छु सेतो दाग, पागलपन, कुष्ठरोग र सबै नराम्रा रोगहरूबाट।", "नराम्रा रोगहरूबाट सुरक्षा।", "स्वास्थ्य रक्षाको मसनून दुआ।"),
        "dua_fear_people" to DuaText("शत्रु वा अत्याचारीको डर", "हे अल्लाह! हामी तपाईंलाई उनीहरूको सामु राख्छौँ र उनीहरूको खराबीबाट तपाईंको शरण माग्छौँ।", "कुनै समूह वा व्यक्तिको खराबीको डर भएमा।", "नबी ﷺ कुनै समूहबाट खतरा महसुस गर्दा यो भन्नुहुन्थ्यो।"),
        "dua_shirk_protection" to DuaText("लुकेको शिर्कबाट सुरक्षा", "हे अल्लाह! म तपाईंको शरण माग्छु जानीजानी तपाईंसँग शिर्क गर्नबाट, र अनजानमा भएकोमा क्षमा माग्छु।", "देखावटी र लुकेको शिर्कबाट बच्न।", "लुकेको शिर्क कमिलाको हिँडाइभन्दा पनि सूक्ष्म हुन्छ।"),
        "dua_rain" to DuaText("वर्षा हुँदा", "हे अल्लाह! लाभदायक वर्षा बर्साउनुहोस्।", "वर्षा हुँदा।", "वर्षा दुआ स्वीकार हुने समय हो।"),
        "dua_after_rain" to DuaText("वर्षापछि", "अल्लाहको अनुग्रह र कृपाले हामीमाथि वर्षा भयो।", "वर्षापछि।", "यो भन्ने व्यक्ति अल्लाहमाथि ईमान राख्ने हो।"),
        "dua_istisqa" to DuaText("वर्षाको प्रार्थना (इस्तिस्का)", "हे अल्लाह! हामीमाथि वर्षा बर्साउनुहोस् (तीन पटक)।", "वर्षा नभएमा।", "नबी ﷺ ले जुम्माको खुत्बामा यो दुआ गर्नुभयो र वर्षा भयो।"),
        "dua_heavy_rain" to DuaText("अतिवृष्टि", "हे अल्लाह! हाम्रो वरिपरि (बर्साउनुहोस्), हामीमाथि होइन।", "वर्षा धेरै भएमा।", "नबी ﷺ को दुआले बादल हटे।"),
        "dua_wind" to DuaText("हावाहुरी चल्दा", "हे अल्लाह! म तपाईंसँग यसको भलाइ, यसभित्र भएको भलाइ र जुन कुरासहित यो पठाइएको हो त्यसको भलाइ माग्छु, र यसको खराबी, यसभित्र भएको खराबी र जुन कुरासहित पठाइएको हो त्यसको खराबीबाट तपाईंको शरण माग्छु।", "तेज हावा/आँधी चल्दा।", "नबी ﷺ आँधीको समयमा यो दुआ गर्नुहुन्थ्यो।"),
        "dua_thunder" to DuaText("गर्जन सुन्दा", "पवित्र हुनुहुन्छ उहाँ जसको प्रशंसासहित गर्जनले तस्बीह गर्छ र फरिश्ताहरूले पनि उहाँको डरले।", "गर्जन सुन्दा — अब्दुल्लाह बिन जुबैर (र.) को अभ्यास।", "सूरह रअद (१३:१३) बाट लिइएको।"),
        "dua_new_moon" to DuaText("नयाँ चन्द्रमा देख्दा", "हे अल्लाह! यो चन्द्रमालाई हामीमाथि बरकत, ईमान, सुरक्षा र इस्लामसहित उदाउनुहोस्। (हे चन्द्रमा!) मेरा र तिम्रा रब अल्लाह हुनुहुन्छ।", "नयाँ चन्द्रमा देखेर।", "हरेक नयाँ महिनाको मसनून दुआ।"),
        "dua_janaza_adult" to DuaText("जनाजाको नमाज (वयस्क)", "हे अल्लाह! हाम्रा जीवित र मृत, उपस्थित र अनुपस्थित, साना र ठूला, पुरुष र महिला सबैलाई क्षमा गर्नुहोस्। हे अल्लाह! हामीमध्ये जसलाई जीवित राख्नुहुन्छ उसलाई इस्लाममा जीवित राख्नुहोस्, र जसलाई मृत्यु दिनुहुन्छ उसलाई ईमानमा मृत्यु दिनुहोस्।", "जनाजाको तेस्रो तकबीरपछि।", "वयस्क मृतकको मसनून दुआ।"),
        "dua_janaza_child" to DuaText("जनाजाको नमाज (बच्चा)", "हे अल्लाह! यसलाई हाम्रा लागि अगाडि जाने (आतिथेय) बनाउनुहोस्, यसलाई हाम्रा लागि प्रतिफल र सञ्चय बनाउनुहोस्, र यसलाई हाम्रा लागि सिफारिस गर्ने र जसको सिफारिस स्वीकार हुन्छ त्यस्तो बनाउनुहोस्।", "नाबालक बच्चाको जनाजामा (छोरी भए 'इज्अल्हा')।", "हनफीहरूमा प्रचलित मसनून दुआ।"),
        "dua_mayyit_awf" to DuaText("मृतकका लागि विस्तृत दुआ", "हे अल्लाह! यसलाई क्षमा गर्नुहोस्, यसमाथि दया गर्नुहोस्, यसलाई सुरक्षा दिनुहोस्, यसलाई माफ गर्नुहोस्, यसको सत्कार सम्मानजनक बनाउनुहोस्, यसको चिहान फराकिलो बनाउनुहोस्, यसलाई पानी, हिउँ र असिनाले धुनुहोस्, र यसलाई पापबाट यसरी सफा गर्नुहोस् जसरी सेतो कपडा मैलोबाट सफा गरिन्छ।", "जनाजामा वा मृतकका लागि।", "औफ बिन मालिक (र.) ले चाहनुभयो कि काश यो मृतक म भएको भए।"),
        "dua_visiting_graves" to DuaText("चिहानको भ्रमण", "हे मोमिन र मुस्लिम बासिन्दाहरू, तिमीहरूमाथि शान्ति होस्। हामी पनि इन शा अल्लाह तिमीहरूसँग मिल्नेवाला छौँ। म अल्लाहसँग हाम्रा र तिमीहरूका लागि सुरक्षा माग्छु।", "चिहानमा प्रवेश गर्दा।", "चिहानको भ्रमणले मृत्यु र आखिरतको सम्झना गराउँछ।"),
        "dua_closing_eyes" to DuaText("मृतकका आँखा बन्द गर्दा", "हे अल्लाह! (फलानो) लाई क्षमा गर्नुहोस्, मार्गदर्शित मानिसहरूमा यसको दर्जा उच्च पार्नुहोस्, यसको पछि बाँकी रहेकाहरूमा यसको उत्तराधिकारी बन्नुहोस्, हे सारा संसारका रब! हामीलाई र यसलाई क्षमा गर्नुहोस्, यसको चिहान फराकिलो बनाउनुहोस् र त्यसमा प्रकाश दिनुहोस्।", "मृतकका आँखा बन्द गर्दा (नाम लिएर)।", "नबी ﷺ ले अबू सलमा (र.) का लागि यो दुआ गर्नुभयो।"),
        "dua_condolence" to DuaText("समवेदना (ताजियत)", "निश्चय नै अल्लाहकै हो जे उहाँले लिनुभयो र उहाँकै हो जे उहाँले दिनुभयो, र उहाँसँग हरेक कुराको निश्चित समय छ, त्यसैले धैर्य गर र पुण्यको आशा राख।", "कसैको निधनमा परिवारलाई समवेदना।", "नबी ﷺ ले आफ्नी छोरीलाई यो सन्देश पठाउनुभयो।"),
        "dua_placing_in_grave" to DuaText("मृतकलाई चिहानमा राख्दा", "अल्लाहको नाममा र रसूलुल्लाह ﷺ को मिल्लतमा।", "मृतकलाई चिहानमा ओराल्दा।", "दफनको मसनून दुआ।"),
        "dua_sneezing" to DuaText("हाच्छिउँ आउँदा", "सम्पूर्ण प्रशंसा अल्लाहका लागि। — अल्लाहले तिमीमाथि दया गरून्। — अल्लाहले तिमीलाई मार्गदर्शन देऊन् र तिम्रो अवस्था सुधारून्।", "हाच्छिउँ आउँदा; सुन्नेले 'यरहमुकल्लाह' भन्छ, अनि हाच्छिउँ गर्नेले जवाफ दिन्छ।", "मुस्लिमको मुस्लिममाथिको अधिकारमध्ये एक।"),
        "dua_toilet_enter" to DuaText("शौचालयमा प्रवेश", "अल्लाहको नाममा। हे अल्लाह! म अपवित्र पुरुष र महिला जिन्नहरूबाट तपाईंको शरण माग्छु।", "बायाँ खुट्टा राखेर शौचालयमा प्रवेश गर्नुअघि।", "बिस्मिल्लाह जिन्न र मानिसको गुप्ताङ्गबीच पर्दा बन्छ।"),
        "dua_toilet_exit" to DuaText("शौचालयबाट निस्कँदा", "(हे अल्लाह!) म तपाईंको क्षमा माग्छु।", "दायाँ खुट्टा बाहिर निकालेर शौचालयबाट निस्कँदा।", "नबी ﷺ शौचालयबाट निस्केर यो भन्नुहुन्थ्यो।"),
        "dua_thanking" to DuaText("कसैलाई धन्यवाद", "अल्लाहले तिमीलाई उत्तम प्रतिफल देऊन्।", "कसैले उपकार गरेमा।", "जसले यो भन्यो उसले प्रशंसाको हक पूरा गर्यो।"),
        "dua_love_for_allah" to DuaText("कसैले 'म तिमीलाई अल्लाहका लागि माया गर्छु' भन्दा", "जसको लागि तिमीले मलाई माया गर्यौ, उहाँ (अल्लाह) ले तिमीलाई माया गरून्।", "कसैले 'म तिमीलाई अल्लाहका लागि माया गर्छु' भन्दा।", "अल्लाहका लागि मायाको मसनून जवाफ।"),
        "dua_seeing_muslim_smile" to DuaText("सलाम", "तिमीमाथि शान्ति, अल्लाहको कृपा र उहाँका बरकतहरू होऊन्।", "मुस्लिमलाई भेट्दा।", "पूर्ण सलाम भन्दा तीस पुण्य पाइन्छ।"),
        "dua_dressing" to DuaText("लुगा लगाउँदा", "सम्पूर्ण प्रशंसा अल्लाहका लागि जसले मलाई यो लुगा लगाइदिनुभयो र मेरो कुनै शक्ति र सामर्थ्यबिना दिनुभयो।", "लुगा लगाउँदा।", "पहिलेका पापको क्षमाको शुभसमाचार।"),
        "dua_rooster_donkey" to DuaText("भाले वा गधाको आवाज सुन्दा", "हे अल्लाह! म तपाईंको अनुग्रह माग्छु (भाले)। — म धिक्कारिएको शैतानबाट अल्लाहको शरण माग्छु (गधा)।", "भालेको बासमा अल्लाहको अनुग्रह माग्नुहोस्, गधाको कराइमा शैतानबाट शरण।", "भालेले फरिश्ता देख्छ र गधाले शैतान।"),
        "dua_something_liked" to DuaText("मनपर्ने कुरा देख्दा (नजरबाट बचाउ)", "जे अल्लाहले चाहनुभयो। हे अल्लाह! यसमा बरकत दिनुहोस्।", "कसैको राम्रो कुरा देखेर बरकतको दुआ दिनुहोस्।", "बरकतको दुआ दिँदा नजर लाग्दैन।"),
        "dua_sell_buy_debt_repaid" to DuaText("ऋण फिर्ता गर्दा", "अल्लाहले तिम्रो परिवार र सम्पत्तिमा बरकत देऊन्।", "ऋण फिर्ता गर्दा ऋणदाताका लागि।", "ऋणको बदला धन्यवाद र भुक्तानी हो।"),
        "dua_talbiyah" to DuaText("तल्बिया", "म उपस्थित छु, हे अल्लाह म उपस्थित छु। म उपस्थित छु, तपाईंको कोही साझेदार छैन, म उपस्थित छु। निश्चय नै सम्पूर्ण प्रशंसा, कृपा र राज्य तपाईंकै हो, तपाईंको कोही साझेदार छैन।", "एहराम बाँधेपछि ठूलो स्वरमा।", "हज र उमराको प्रतीक।"),
        "dua_yamani_hajar" to DuaText("रुक्न-ए-यमानी र हजर-ए-अस्वदबीच", "हे हाम्रा रब! हामीलाई संसारमा पनि भलाइ दिनुहोस् र आखिरतमा पनि भलाइ दिनुहोस्, र हामीलाई आगोको सजायबाट बचाउनुहोस्।", "तवाफमा रुक्न-ए-यमानी र हजर-ए-अस्वदबीच।", "नबी ﷺ तवाफमा यस ठाउँमा यो पढ्नुहुन्थ्यो।"),
        "dua_safa_marwa" to DuaText("सफा र मरवामा", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, राज्य र प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ। अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँले आफ्नो वाचा पूरा गर्नुभयो, आफ्नो दासलाई मद्दत गर्नुभयो र एक्लै सबै सेनालाई पराजित गर्नुभयो।", "सफामा चढेर किब्लातर्फ फर्केर (तीन पटक)।", "सफा र मरवामा नबी ﷺ को जिक्र।"),
        "dua_arafah" to DuaText("अरफाको दिनको सर्वोत्तम दुआ", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, राज्य र प्रशंसा उहाँकै हो र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "अरफाको दिन — सर्वोत्तम दुआ।", "सर्वोत्तम दुआ अरफाको दिनको दुआ हो, र सर्वोत्तम वाक्य यही हो।"),
        "dua_takbeer_tashreeq" to DuaText("तकबीर-ए-तशरीक", "अल्लाह सबैभन्दा महान हुनुहुन्छ, अल्लाह सबैभन्दा महान हुनुहुन्छ। अल्लाहबाहेक कोही पूज्य छैन। अल्लाह सबैभन्दा महान हुनुहुन्छ, अल्लाह सबैभन्दा महान हुनुहुन्छ, र सम्पूर्ण प्रशंसा अल्लाहकै लागि हो।", "९ जिल्हिज्जा फज्रदेखि १३ जिल्हिज्जा अस्रसम्म हरेक फर्ज नमाजपछि।", "अली र इब्न मसऊद (र.) बाट वर्णित — हनफीहरूमा वाजिब।"),
        "dua_zamzam" to DuaText("जमजम पिउँदा", "हे अल्लाह! म तपाईंसँग उपयोगी ज्ञान, प्रशस्त जीविका र हरेक रोगबाट निको हुने वरदान माग्छु।", "जमजम पिउँदा जुन नियत छ त्यसको दुआ गर्नुहोस्।", "जमजम जुन नियतले पिइन्छ त्यसैका लागि हो (इब्न माजा ३०६२)।"),
        "dua_q_ma_khalaqta_batila" to DuaText("सृष्टिमाथि चिन्तन", "हे हाम्रा रब! तपाईंले यो सब व्यर्थ सृष्टि गर्नुभएन, तपाईं पवित्र हुनुहुन्छ, त्यसैले हामीलाई आगोको सजायबाट बचाउनुहोस्।", "आकाश र पृथ्वीको सृष्टिमाथि चिन्तन गर्नेहरूको दुआ।", "बुद्धिमानहरू (उलुल अल्बाब) को दुआ।"),
        "dua_q_sami_na_munadiyan" to DuaText("हामीले ईमानको आह्वानकर्तालाई सुन्यौँ", "हे हाम्रा रब! हामीले एक आह्वानकर्तालाई ईमानतर्फ बोलाउँदै गरेको सुन्यौँ कि आफ्ना रबमाथि ईमान ल्याओ, त्यसैले हामीले ईमान ल्यायौँ। हे हाम्रा रब! हाम्रा पाप क्षमा गर्नुहोस्, हाम्रा खराबीहरू हटाउनुहोस् र हामीलाई असल मानिसहरूसँग मृत्यु दिनुहोस्।", "ईमान र असल मानिसहरूसँग मृत्युको दुआ।", "क्षमा र राम्रो अन्त्यको दुआ।"),
        "dua_q_atina_ma_waadtana" to DuaText("जे वाचा गर्नुभयो त्यो दिनुहोस्", "हे हाम्रा रब! तपाईंले आफ्ना रसूलहरूमार्फत जे वाचा गर्नुभयो त्यो हामीलाई दिनुहोस्, र कयामतको दिन हामीलाई अपमानित नगर्नुहोस्, निश्चय नै तपाईं वाचा तोड्नुहुन्न।", "कयामतको अपमानबाट शरण।", "आखिरतमा सम्मानको माग।"),
        "dua_q_israfana" to DuaText("हाम्रा अतिहरू क्षमा गर्नुहोस्", "हे हाम्रा रब! हाम्रा पाप र हाम्रा काममा हाम्रा अतिहरू क्षमा गर्नुहोस्, हाम्रा खुट्टा दृढ पार्नुहोस् र काफिर समुदायविरुद्ध हामीलाई मद्दत गर्नुहोस्।", "पहिलेका नबीहरूका साथीहरूको दुआ।", "दृढता र क्षमाको दुआ।"),
        "dua_q_jamiun_nas" to DuaText("तपाईं मानिसहरूलाई जम्मा गर्नुहुनेछ", "हे हाम्रा रब! निश्चय नै तपाईं मानिसहरूलाई त्यस दिन जम्मा गर्नुहुनेछ जसमा कुनै शंका छैन। निश्चय नै अल्लाह वाचा तोड्नुहुन्न।", "कयामतमा विश्वासको स्वीकृति।", "ज्ञानमा दृढ मानिसहरूको दुआ।"),
        "dua_q_maash_shahidin" to DuaText("हामीलाई साक्षीहरूमा लेख्नुहोस्", "हे हाम्रा रब! हामीले ईमान ल्यायौँ, त्यसैले हामीलाई साक्षी दिनेहरूसँग लेख्नुहोस्।", "सत्य चिनेर ईमान ल्याउनेहरूको दुआ।", "ईमानको स्वीकृतिको दुआ।"),
        "dua_q_la_tajalna_zalimin" to DuaText("अत्याचारीहरूसँग नराख्नुहोस्", "हे हाम्रा रब! हामीलाई अत्याचारी समुदायसँग नराख्नुहोस्।", "अअराफवासीहरूको दुआ।", "अत्याचारीहरूको परिणामबाट शरण।"),
        "dua_q_tawaffana_muslimin" to DuaText("धैर्य र मुस्लिम भएर मृत्यु", "हे हाम्रा रब! हामीमाथि धैर्य खन्याउनुहोस् र हामीलाई मुस्लिम अवस्थामा मृत्यु दिनुहोस्।", "फिरऔनका जादूगरहरूले ईमान ल्याउँदाको दुआ।", "परीक्षामा धैर्य र ईमानमा अन्त्य।"),
        "dua_q_la_tajalna_fitnah" to DuaText("अत्याचारीहरूका लागि परीक्षा नबनाउनुहोस्", "हामीले अल्लाहमाथि भरोसा गर्यौँ। हे हाम्रा रब! हामीलाई अत्याचारी समुदायका लागि परीक्षा नबनाउनुहोस्, र आफ्नो कृपाले हामीलाई काफिर समुदायबाट मुक्ति दिनुहोस्।", "मूसा (अ.) को समुदायको दुआ।", "अत्याचार र अत्याचारीबाट मुक्तिको दुआ।"),
        "dua_q_nuh_ma_laysa_li" to DuaText("क्षमाका लागि नूह (अ.) को दुआ", "हे मेरा रब! म तपाईंको शरण माग्छु कि तपाईंसँग त्यस्तो कुरा मागूँ जसको मलाई ज्ञान छैन। यदि तपाईंले मलाई क्षमा गर्नुभएन र ममाथि दया गर्नुभएन भने म घाटा उठाउनेहरूमध्ये हुनेछु।", "नूह (अ.) को तौबाको दुआ।", "आदरसहित दुआ गर्ने शिक्षा।"),
        "dua_q_mudkhala_sidq" to DuaText("सत्यसहित प्रवेश र निस्कने", "हे मेरा रब! मलाई सत्यसहित प्रवेश गराउनुहोस् र सत्यसहित निकाल्नुहोस्, र आफ्नो तर्फबाट मलाई सहयोगी शक्ति दिनुहोस्।", "कुनै नयाँ काम, घर वा ठाउँमा प्रवेश गर्नुअघि।", "हिजरतको समयमा नबी ﷺ लाई सिकाइएको दुआ।"),
        "dua_q_la_tadharni_fardan" to DuaText("मलाई एक्लै नछोड्नुहोस् (जकरिया अ.)", "हे मेरा रब! मलाई एक्लै नछोड्नुहोस्, र तपाईं सर्वोत्तम उत्तराधिकारी हुनुहुन्छ।", "सन्तान माग्नका लागि।", "यो दुआमा अल्लाहले यह्या (अ.) दिनुभयो।"),
        "dua_q_munzalan_mubarakan" to DuaText("बरकतमय ठाउँमा ओराल्नुहोस्", "हे मेरा रब! मलाई बरकतमय ठाउँमा ओराल्नुहोस्, र तपाईं सर्वोत्तम ओराल्नुहुने हुनुहुन्छ।", "नयाँ घरमा सर्दा वा कतै ओर्लँदा — नूह (अ.) को दुआ।", "नयाँ ठाउँमा बरकतको दुआ।"),
        "dua_q_amanna_faghfir" to DuaText("हामीले ईमान ल्यायौँ, हामीलाई क्षमा गर्नुहोस्", "हे हाम्रा रब! हामीले ईमान ल्यायौँ, त्यसैले हामीलाई क्षमा गर्नुहोस् र हामीमाथि दया गर्नुहोस्, र तपाईं सर्वोत्तम दया गर्नुहुने हुनुहुन्छ।", "अल्लाहका असल दासहरूको दुआ।", "क्षमा र कृपाको व्यापक दुआ।"),
        "dua_q_isrif_jahannam" to DuaText("जहन्नमको सजाय हटाउनुहोस्", "हे हाम्रा रब! जहन्नमको सजाय हामीबाट हटाउनुहोस्, निश्चय नै त्यसको सजाय टाँसिरहने छ। निश्चय नै त्यो नराम्रो बासस्थान र ठाउँ हो।", "रहमानका दासहरूको दुआ।", "जहन्नमबाट शरणको कुरआनी दुआ।"),
        "dua_q_hab_li_hukman" to DuaText("बुद्धि र जन्नत (इब्राहीम अ.)", "हे मेरा रब! मलाई बुद्धि दिनुहोस् र असल मानिसहरूसँग मिलाउनुहोस्, पछिका पुस्तामा मेरो असल सम्झना जारी राख्नुहोस्, र मलाई आनन्दमय जन्नतका उत्तराधिकारीहरूमध्ये बनाउनुहोस्।", "बुद्धि, असल मानिसको संगत र जन्नतको माग।", "इब्राहीम (अ.) को व्यापक दुआ।"),
        "dua_q_lut_najjini_ahli" to DuaText("मेरो परिवारलाई बचाउनुहोस् (लूत अ.)", "हे मेरा रब! मलाई र मेरो परिवारलाई उनीहरूका कर्म (को परिणाम) बाट मुक्ति दिनुहोस्।", "खराब वातावरणबाट परिवारको सुरक्षा।", "खराबीबाट परिवारको सुरक्षा।"),
        "dua_q_sulaiman_awzini" to DuaText("कृतज्ञताका लागि सुलैमान (अ.) को दुआ", "हे मेरा रब! मलाई सामर्थ्य दिनुहोस् कि म तपाईंको त्यो कृपाको धन्यवाद गरूँ जुन तपाईंले ममाथि र मेरा आमाबुबामाथि गर्नुभयो, र यस्तो असल कर्म गरूँ जुन तपाईंलाई मन पर्छ, र आफ्नो कृपाले मलाई आफ्ना असल दासहरूमा सामेल गर्नुहोस्।", "कृपाको धन्यवाद गर्ने सामर्थ्य।", "सुलैमान (अ.) को कृतज्ञताको दुआ।"),
        "dua_q_musa_zalamtu" to DuaText("मैले आफैँमाथि अन्याय गरेँ (मूसा अ.)", "हे मेरा रब! मैले आफैँमाथि अन्याय गरेँ, त्यसैले मलाई क्षमा गर्नुहोस्।", "गल्ती भएपछि तुरुन्त तौबा।", "अल्लाहले मूसा (अ.) लाई क्षमा गर्नुभयो।"),
        "dua_q_musa_najjini" to DuaText("अत्याचारीहरूबाट बचाउनुहोस् (मूसा अ.)", "हे मेरा रब! मलाई अत्याचारी समुदायबाट मुक्ति दिनुहोस्।", "अत्याचारीहरूको डरमा।", "मिस्रबाट निस्कँदा मूसा (अ.) को दुआ।"),
        "dua_q_lut_unsurni" to DuaText("उपद्रवीहरूविरुद्ध मद्दत (लूत अ.)", "हे मेरा रब! उपद्रव गर्ने समुदायविरुद्ध मलाई मद्दत गर्नुहोस्।", "उपद्रवीहरूविरुद्ध मद्दत।", "सत्यमा दृढ रहनेहरूको दुआ।"),
        "dua_q_hab_li_salihin" to DuaText("असल सन्तानका लागि इब्राहीम (अ.) को दुआ", "हे मेरा रब! मलाई असल (सन्तान) दिनुहोस्।", "असल सन्तानको माग।", "यो दुआमा इस्माईल (अ.) प्राप्त हुनुभयो।"),
        "dua_q_wasita_kulla_shay" to DuaText("अर्श बोक्ने फरिश्ताहरूको दुआ", "हे हाम्रा रब! तपाईंको कृपा र ज्ञानले हरेक कुरालाई घेरेको छ, त्यसैले जसले तौबा गरे र तपाईंको मार्ग पछ्याए उनीहरूलाई क्षमा गर्नुहोस्, र उनीहरूलाई जहन्नमको सजायबाट बचाउनुहोस्।", "अर्श बोक्ने फरिश्ताहरू मोमिनहरूका लागि यो दुआ गर्छन्।", "फरिश्ताहरूको दुआमा सामेल हुने नियतले।"),
        "dua_q_ikhwanina" to DuaText("हामीभन्दा अघिका भाइहरूका लागि", "हे हाम्रा रब! हामीलाई र हाम्रा ती भाइहरूलाई क्षमा गर्नुहोस् जो हामीभन्दा अघि ईमान ल्याए, र हाम्रा हृदयमा ईमानवालाहरूप्रति कुनै द्वेष नराख्नुहोस्। हे हाम्रा रब! निश्चय नै तपाईं अत्यन्त स्नेही, दयालु हुनुहुन्छ।", "पहिलेका मोमिनहरूका लागि र हृदयको शुद्धताको दुआ।", "सहाबा (र.) र पहिलेका मोमिनहरूका लागि दुआ।"),
        "dua_q_alayka_tawakkalna" to DuaText("तपाईंमाथि नै हामीले भरोसा गर्यौँ (इब्राहीम अ.)", "हे हाम्रा रब! हामीले तपाईंमाथि भरोसा गर्यौँ, तपाईंतर्फ फर्कियौँ र तपाईंतर्फ नै फर्किनु छ। हे हाम्रा रब! हामीलाई काफिरहरूका लागि परीक्षा नबनाउनुहोस् र हामीलाई क्षमा गर्नुहोस्। हे हाम्रा रब! निश्चय नै तपाईं प्रभुत्वशाली, बुद्धिमान हुनुहुन्छ।", "इब्राहीम (अ.) र उहाँका साथीहरूको दुआ।", "भरोसा र फर्किने दुआ।"),
        "dua_q_atmim_nurana" to DuaText("हाम्रो प्रकाश पूर्ण गर्नुहोस्", "हे हाम्रा रब! हाम्रा लागि हाम्रो प्रकाश पूर्ण गर्नुहोस् र हामीलाई क्षमा गर्नुहोस्, निश्चय नै तपाईं हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "कयामतको दिन मोमिनहरूको दुआ।", "पुल-सिरातमा प्रकाशको माग।"),
        "dua_q_asiya_baytan" to DuaText("जन्नतमा घर (आसिया)", "हे मेरा रब! मेरा लागि आफ्नो नजिक जन्नतमा घर बनाइदिनुहोस्, र मलाई फिरऔन र उसका कर्मबाट मुक्ति दिनुहोस्, र अत्याचारी समुदायबाट मुक्ति दिनुहोस्।", "फिरऔनकी श्रीमती आसियाको दुआ।", "अल्लाहले उहाँलाई मोमिनहरूका लागि उदाहरण बनाउनुभयो।"),
        "dua_adhan_response" to DuaText("अजानको जवाफ", "अल्लाहबाहेक न कुनै शक्ति छ न कुनै सामर्थ्य।", "मुअज्जिनले जे भन्छ त्यही दोहोर्याउनुहोस्; 'हय्या अलस्सलाह' र 'हय्या अलल फलाह' मा यो भन्नुहोस्।", "मनबाट जवाफ दिने जन्नतमा प्रवेश गर्नेछ।"),
        "dua_adhan_shahadah" to DuaText("मुअज्जिनको शहादतपछि", "र म पनि साक्षी दिन्छु कि अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, र मुहम्मद ﷺ उहाँका दास र रसूल हुनुहुन्छ। म अल्लाहलाई रब, मुहम्मद ﷺ लाई रसूल र इस्लामलाई दीनको रूपमा पाएर सन्तुष्ट छु।", "मुअज्जिनको शहादतैन सुनेर।", "उसका पाप क्षमा हुन्छन्।"),
        "dua_istiftah_baid" to DuaText("सुरुको दुआ: मलाई पापबाट टाढा राख्नुहोस्", "हे अल्लाह! मेरो र मेरा पापहरूबीच त्यति दूरी बनाउनुहोस् जति तपाईंले पूर्व र पश्चिमबीच बनाउनुभयो। हे अल्लाह! मलाई पापबाट यसरी सफा गर्नुहोस् जसरी सेतो कपडा मैलोबाट सफा गरिन्छ। हे अल्लाह! मेरा पापहरू पानी, हिउँ र असिनाले धोइदिनुहोस्।", "तकबीर-ए-तहरीमापछि (सनाको सट्टा पनि पढ्न सकिन्छ)।", "नबी ﷺ तकबीर र किराअतबीच यो पढ्नुहुन्थ्यो।"),
        "dua_hamdan_kathiran" to DuaText("रुकूपछि प्रशस्त प्रशंसा", "हे हाम्रा रब! तपाईंकै लागि प्रशंसा — धेरै, पवित्र र बरकतमय प्रशंसा।", "रुकूबाट उठेर 'रब्बना लकल हम्द' सँगै।", "तीसभन्दा बढी फरिश्ताहरू यसलाई पहिले लेख्न होडबाजी गरिरहेका थिए।"),
        "dua_subbuhun_quddus" to DuaText("सुब्बूहुन कुद्दूस (रुकू र सजदा)", "(अल्लाह) अत्यन्त पवित्र, अत्यन्त पुनीत हुनुहुन्छ, फरिश्ता र रूह (जिब्रील) का रब।", "रुकू र सजदामा।", "नबी ﷺ रुकू र सजदामा यो पढ्नुहुन्थ्यो।"),
        "dua_sujood_dhanbi_kullah" to DuaText("सजदामा: मेरा सबै पाप क्षमा गर्नुहोस्", "हे अल्लाह! मेरा सबै पाप क्षमा गर्नुहोस् — साना र ठूला, पहिलेका र पछिका, खुला र लुकेका।", "सजदामा।", "सजदा दुआ स्वीकार हुने ठाउँ हो।"),
        "dua_sujood_ridaka" to DuaText("तपाईंको प्रसन्नताको शरण", "हे अल्लाह! म तपाईंको प्रसन्नताद्वारा तपाईंको अप्रसन्नताबाट, तपाईंको क्षमाद्वारा तपाईंको सजायबाट शरण माग्छु, र तपाईंबाट तपाईंकै शरण माग्छु। म तपाईंको प्रशंसा पूर्ण रूपमा गर्न सक्दिनँ, तपाईं त्यस्तै हुनुहुन्छ जस्तो तपाईंले आफ्नो प्रशंसा गर्नुभयो।", "सजदामा — आइशा (र.) ले नबी ﷺ लाई यो पढ्दै गरेको सुन्नुभयो।", "नबी ﷺ को सजदाको दुआ।"),
        "dua_tashahhud" to DuaText("तशह्हुद (अत्तहिय्यात)", "सबै मौखिक, शारीरिक र आर्थिक उपासना अल्लाहका लागि हुन्। हे नबी! तपाईंमाथि सलाम, अल्लाहको कृपा र उहाँका बरकतहरू होऊन्। हामीमाथि र अल्लाहका असल दासहरूमाथि सलाम होस्। म साक्षी दिन्छु कि अल्लाहबाहेक कोही पूज्य छैन, र साक्षी दिन्छु कि मुहम्मद ﷺ उहाँका दास र रसूल हुनुहुन्छ।", "हरेक कादामा — अब्दुल्लाह बिन मसऊद (र.) को वर्णन (हनफीहरूको अभ्यास)।", "नबी ﷺ यसलाई कुरआनको सूरह जस्तै सिकाउनुहुन्थ्यो।"),
        "dua_sajdah_tilawah" to DuaText("सजदा-ए-तिलावत", "मेरो अनुहारले उहाँलाई सजदा गर्यो जसले यसलाई सृष्टि गर्नुभयो र आफ्नो शक्ति र सामर्थ्यले यसका कान र आँखा बनाउनुभयो।", "सजदा-ए-तिलावतमा।", "नबी ﷺ रातको सजदा-ए-तिलावतमा यो पढ्नुहुन्थ्यो।"),
        "dua_after_witr" to DuaText("वित्रपछि", "पवित्र हुनुहुन्छ राजा, अत्यन्त पुनीत।", "वित्रको सलामपछि तीन पटक, तेस्रो पटक ठूलो स्वरमा।", "नबी ﷺ वित्रपछि यो भन्नुहुन्थ्यो।"),
        "dua_tahajjud_nur" to DuaText("तहज्जुदको सुरुको दुआ", "हे अल्लाह! तपाईंकै लागि प्रशंसा हो, तपाईं आकाश, पृथ्वी र तिनमा भएका सबैका धारक हुनुहुन्छ। तपाईंकै लागि प्रशंसा हो, तपाईं आकाश, पृथ्वी र तिनमा भएका सबैका प्रकाश हुनुहुन्छ। तपाईंकै लागि प्रशंसा हो, तपाईं सत्य हुनुहुन्छ, तपाईंको वाचा सत्य हो, तपाईंसँगको भेट सत्य हो, तपाईंको वचन सत्य हो, जन्नत सत्य हो, जहन्नम सत्य हो, नबीहरू सत्य हुन्, मुहम्मद ﷺ सत्य हुनुहुन्छ र कयामत सत्य हो।", "रातको नमाज (तहज्जुद) सुरु गर्दा (दुआको सुरुको भाग)।", "नबी ﷺ तहज्जुदका लागि उठेर यो पढ्नुहुन्थ्यो (पूर्ण दुआ बुखारीमा छ)।"),
        "dua_rabba_jibrail" to DuaText("विवादित विषयमा मार्गदर्शन", "हे अल्लाह, जिब्रील, मीकाईल र इस्राफीलका रब, आकाश र पृथ्वीका सृष्टिकर्ता, लुकेको र खुलाका ज्ञाता! तपाईंले आफ्ना दासहरूबीच ती कुराको निर्णय गर्नुहुनेछ जसमा तिनीहरू मतभेद गर्थे। जुन सत्यमा मतभेद भयो, आफ्नो आदेशले त्यसमा मलाई मार्गदर्शन गर्नुहोस्। निश्चय नै तपाईं जसलाई चाहनुहुन्छ सिधा मार्ग देखाउनुहुन्छ।", "तहज्जुदको सुरुमा — मतभेदको समयमा सत्यको मार्गदर्शन।", "नबी ﷺ रातको नमाज यही दुआले सुरु गर्नुहुन्थ्यो।"),
        "dua_going_to_mosque_nur" to DuaText("मस्जिद जाँदा (प्रकाशको दुआ)", "हे अल्लाह! मेरो हृदयमा प्रकाश दिनुहोस्, मेरा आँखामा प्रकाश, मेरा कानमा प्रकाश, मेरो दायाँ प्रकाश, मेरो बायाँ प्रकाश, मेरो माथि प्रकाश, मेरो तल प्रकाश, मेरो अगाडि प्रकाश, मेरो पछाडि प्रकाश, र मेरा लागि प्रकाश बनाइदिनुहोस्।", "फज्रका लागि मस्जिद जाँदा।", "नबी ﷺ नमाजका लागि निस्कँदा यो पढ्नुहुन्थ्यो।"),
        "dua_waswasa_salah" to DuaText("नमाजमा वसवसा (खिंजब)", "म धिक्कारिएको शैतानबाट अल्लाहको शरण माग्छु।", "नमाजमा शैतानी वसवसा आएमा शरण मागेर बायाँतिर तीन पटक हल्का थुक्नुहोस्।", "उस्मान बिन अबिल आस (र.) ले यसो गर्नुभयो र वसवसा हट्यो।"),
        "dua_alimal_ghayb" to DuaText("अदृश्यका ज्ञाता", "हे अल्लाह, अदृश्य र दृश्यका ज्ञाता, आकाश र पृथ्वीका सृष्टिकर्ता, हरेक कुराका रब र मालिक! म साक्षी दिन्छु कि तपाईंबाहेक कोही पूज्य छैन। म आफ्नो मनको खराबीबाट, र शैतानको खराबी र उसको शिर्कबाट तपाईंको शरण माग्छु।", "बिहान, साँझ र सुत्नुअघि — नबी ﷺ ले अबू बक्र (र.) लाई सिकाउनुभयो।", "मन र शैतानको खराबीबाट सुरक्षा।"),
        "dua_fitratil_islam" to DuaText("इस्लामको फितरतमा", "हामीले इस्लामको फितरतमा, इखलासको कलिमामा, हाम्रा नबी मुहम्मद ﷺ को दीनमा र हाम्रा पिता इब्राहीम (अ.) को मिल्लतमा बिहान गर्यौँ, जो एकनिष्ठ मुस्लिम हुनुहुन्थ्यो र मुशरिकहरूमध्ये हुनुहुन्नथ्यो।", "बिहान।", "हरेक बिहान ईमानको नवीकरण।"),
        "dua_amsayna_fitrah" to DuaText("साँझ इस्लामको फितरतमा", "हामीले इस्लामको फितरतमा, इखलासको कलिमामा, हाम्रा नबी मुहम्मद ﷺ को दीनमा र हाम्रा पिता इब्राहीम (अ.) को मिल्लतमा साँझ गर्यौँ, जो एकनिष्ठ मुस्लिम हुनुहुन्थ्यो र मुशरिकहरूमध्ये हुनुहुन्नथ्यो।", "साँझ।", "हरेक साँझ ईमानको नवीकरण।"),
        "dua_tahleel_10_fajr" to DuaText("फज्र र मगरिबपछि दस पटक तहलील", "अल्लाहबाहेक कोही पूज्य छैन, उहाँ एक्लै हुनुहुन्छ, उहाँको कोही साझेदार छैन, राज्य र प्रशंसा उहाँकै हो, उहाँ नै जीवन दिनुहुन्छ र मृत्यु दिनुहुन्छ, र उहाँ हरेक कुरामा सर्वशक्तिमान हुनुहुन्छ।", "फज्र (र मगरिब) पछि, खुट्टा नफेरी र नबोली दस पटक।", "दस पुण्य, दस पाप क्षमा, दस दर्जा उच्च र दिनभर शैतानबाट सुरक्षा।"),
        "dua_la_hawla_kanz" to DuaText("जन्नतको खजाना", "अल्लाहबाहेक न कुनै शक्ति छ न कुनै सामर्थ्य।", "हरेक समय धेरै।", "यो जन्नतका खजानाहरूमध्ये एक खजाना हो।"),
        "dua_four_beloved_words" to DuaText("सबैभन्दा प्यारा चार वाक्य", "अल्लाह पवित्र हुनुहुन्छ, सम्पूर्ण प्रशंसा अल्लाहका लागि हो, अल्लाहबाहेक कोही पूज्य छैन, र अल्लाह सबैभन्दा महान हुनुहुन्छ।", "अल्लाहलाई सबैभन्दा मनपर्ने वाक्यहरू।", "नबी ﷺ लाई यी वाक्य सूर्य उदाउने हरेक कुराभन्दा प्यारा छन्।"),
        "dua_two_light_words" to DuaText("जिब्रोमा हलुका दुई वाक्य", "अल्लाह पवित्र हुनुहुन्छ र प्रशंसा उहाँकै हो, महान अल्लाह पवित्र हुनुहुन्छ।", "जिब्रोमा हलुका, तराजुमा भारी।", "रहमानलाई प्यारा, जिब्रोमा हलुका र तराजुमा भारी। (बुखारीको अन्तिम हदीस)"),
        "dua_ya_dhal_jalal" to DuaText("या जल जलालि वल इक्राम", "हे महिमा र सम्मानका स्वामी!", "दुआमा यसलाई समातेर राख्नुहोस् — नबी ﷺ को आदेश।", "नबी ﷺ ले भन्नुभयो: 'या जल जलालि वल इक्राम' लाई समातेर राख।"),
        "dua_sleep_wadatu_janbi" to DuaText("तपाईंको नाममा मैले कोल्टे फेरेँ", "हे मेरा रब! तपाईंको नाममा मैले आफ्नो कोल्टे राखेँ र तपाईंकै नाममा उठ्नेछु। यदि तपाईंले मेरो आत्मा रोक्नुभयो भने त्यसमाथि दया गर्नुहोस्, र छोड्नुभयो भने त्यसको यसरी रक्षा गर्नुहोस् जसरी तपाईं आफ्ना असल दासहरूको रक्षा गर्नुहुन्छ।", "ओछ्यान टकटकाएर पल्टेपछि।", "सुत्नुअघि आत्मा अल्लाहको जिम्मामा सुम्पने।"),
        "dua_sleep_khalaqta_nafsi" to DuaText("तपाईंले मेरो आत्मा सृष्टि गर्नुभयो", "हे अल्लाह! तपाईंले मेरो आत्मा सृष्टि गर्नुभयो र तपाईं नै त्यसलाई मृत्यु दिनुहुनेछ। त्यसको मर्नु र बाँच्नु तपाईंकै लागि हो। यदि तपाईंले त्यसलाई जीवित राख्नुभयो भने त्यसको रक्षा गर्नुहोस्, र मृत्यु दिनुभयो भने त्यसलाई क्षमा गर्नुहोस्। हे अल्लाह! म तपाईंसँग सुरक्षा माग्छु।", "सुत्नुअघि — इब्न उमर (र.) को वर्णन।", "नबी ﷺ ले सुत्ने बेला यो पढ्न आदेश दिनुभयो।"),
        "dua_sleep_atamana" to DuaText("सुत्नुअघि कृतज्ञता", "सम्पूर्ण प्रशंसा अल्लाहका लागि जसले हामीलाई खुवाउनुभयो, पिलाउनुभयो, हाम्रो आवश्यकता पूरा गर्नुभयो र बास दिनुभयो। कति मानिसहरू छन् जसको आवश्यकता पूरा गर्ने कोही छैन न बास दिने।", "ओछ्यानमा जाँदा।", "नबी ﷺ ओछ्यानमा जाँदा यो भन्नुहुन्थ्यो।"),
        "dua_sleep_rabbas_samawat" to DuaText("आकाशका रब — हाम्रो ऋण तिरिदिनुहोस्", "हे अल्लाह, आकाश, पृथ्वी र महान अर्शका रब, हाम्रा र हरेक कुराका रब, दाना र बीउ फुटाउनुहुने, तौरात, इन्जील र फुरकान उतार्नुहुने! म हरेक त्यो कुराको खराबीबाट तपाईंको शरण माग्छु जसको निधार तपाईंको हातमा छ। हे अल्लाह! तपाईं नै पहिलो हुनुहुन्छ, तपाईंभन्दा अघि केही छैन; तपाईं नै अन्तिम हुनुहुन्छ, तपाईंपछि केही छैन; तपाईं नै प्रकट हुनुहुन्छ, तपाईंमाथि केही छैन; तपाईं नै गुप्त हुनुहुन्छ, तपाईंबाट लुकेको केही छैन। हाम्रो ऋण तिरिदिनुहोस् र हामीलाई गरिबीबाट मुक्त गर्नुहोस्।", "सुत्नुअघि दायाँ कोल्टे — फातिमा (र.) लाई सिकाइएको।", "ऋण र अभावबाट मुक्तिको दुआ।"),
        "dua_sleep_fear" to DuaText("निद्रामा डर वा बेचैनी", "म अल्लाहका पूर्ण वचनहरूको शरण माग्छु उहाँको क्रोध र सजायबाट, उहाँका दासहरूको खराबीबाट, र शैतानहरूका वसवसा र तिनीहरू मेरो नजिक आउनबाट।", "निद्रामा बेचैनी वा डर लागेमा।", "यसो गर्दा त्यो कुराले हानि गर्दैन।"),
        "dua_waking_afani" to DuaText("ब्युँझँदा: उहाँले मेरो आत्मा फर्काउनुभयो", "सम्पूर्ण प्रशंसा अल्लाहका लागि जसले मेरो शरीरलाई स्वास्थ्य दिनुभयो, मेरो आत्मा मलाई फर्काउनुभयो र मलाई आफ्नो जिक्र गर्ने अनुमति दिनुभयो।", "ब्युँझँदा।", "नयाँ बिहानका लागि कृतज्ञता।"),
        "dua_allahu_rabbi" to DuaText("अल्लाह, अल्लाह मेरा रब हुनुहुन्छ", "अल्लाह, अल्लाह मेरा रब हुनुहुन्छ, म उहाँसँग कुनै कुरालाई साझेदार बनाउँदिनँ।", "दुःख वा चिन्ताको समयमा — नबी ﷺ ले अस्मा बिन्त उमैस (र.) लाई सिकाउनुभयो।", "चिन्ताको समयमा तौहीदको सहारा।"),
    )
}
